function [s, ok] = quad_angles(i, p)
%QUAD_ANGLES  The Sun in the head's frame (unit) from the four currents i (++, -+, --, +-), and whether it is valid.
%   i: real[1][4] (passed a plain number)
%   p: SunHead (passed rec)
%   returns s: real[1][3] (passed a plain number)
%   returns ok: bool (passed true or false)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    s = zeros(3, 1);
    ok = false;
    tot = (((i(1) + i(2)) + i(3)) + i(4));
    ok = (tot > p.min_frac);
    s = [0; 0; 1];
    if ok
        rx = (((i(1) + i(4)) - (i(2) + i(3))) / tot);
        ry = (((i(1) + i(2)) - (i(3) + i(4))) / tot);
        s = asils.models.facets.unit_or_zero([(((p.a / 2) * rx) / p.h); (((p.a / 2) * ry) / p.h); 1]);
    end
end
